-- 205 : couvrir les douze départements par une veille de presse locale.
--
-- Problème mesuré : les sources de presse déclarées `cti` passent la porte
-- cyber ; un titre de la vie locale (« le marché de Noël ouvre ») est rétrogradé
-- en `presse` puis refusé. Un département rural sans incident cyber nommé
-- n'avait donc aucun fait régional récent, même quand sa presse locale
-- publiait. La famille `presse_locale` est une veille de provenance : le
-- département éditeur est le signal, le vocabulaire du titre ne décide pas.
--
-- Cette migration pose le socle :
--   1. `event.dept` (code INSEE) + index, pour compter la couverture ;
--   2. 27 sources de presse locale départementales vérifiées le 2026-11-21
--      (un flux RSS ou éditorial par éditeur, jamais une source nationale) ;
--   3. un instantané de 120 titres réels (10 par département) issus du corpus
--      gelé `bench/corpus/articles-presse-na.jsonl`, complété pour la Vienne
--      par deux faits de `bench/corpus/incidents-vienne.jsonl`. Les dates de
--      publication sont conservées : l'instantané est daté, pas fabriqué.
--
-- La collecte suivante entretient la famille : `generic.ts` admet les items
-- d'une source `presse_locale` avec son `department`, sans porte cyber et
-- sans rattachement textuel. Aucune donnée personnelle n'est ajoutée : titre,
-- URL publique, éditeur et date de publication uniquement.

BEGIN;

ALTER TABLE event ADD COLUMN IF NOT EXISTS dept text;
COMMENT ON COLUMN event.dept IS
  'Code INSEE du département éditeur pour une veille presse_locale ; NULL sinon.';
CREATE INDEX IF NOT EXISTS event_presse_locale_dept_idx
  ON event (dept, observed_at DESC)
  WHERE family = 'presse_locale' AND dept IS NOT NULL;

-- Le contrat applicatif (packages/shared) porte la famille ; si une instance
-- historique a un CHECK sur event.family, on l'élargit sans jamais en créer un.
DO $$
DECLARE
  con     record;
  wanted  text := $check$CHECK (family IN ('ransomware','vuln','phishing','malware','cert','cert_fr','typosquat','reputation','cti','presse','leaks','paste','presse_cyber','presse_locale'))$check$;
  changed boolean := false;
BEGIN
  FOR con IN
    SELECT c.conname, pg_get_constraintdef(c.oid) AS def
      FROM pg_constraint c
     WHERE c.conrelid = 'event'::regclass
       AND c.contype = 'c'
       AND pg_get_constraintdef(c.oid) ILIKE '%family%'
  LOOP
    IF con.def ILIKE '%presse_locale%' THEN
      RAISE NOTICE 'migrate-205 : % accepte déjà presse_locale', con.conname;
      CONTINUE;
    END IF;
    IF EXISTS (
      SELECT 1 FROM event
       WHERE family NOT IN ('ransomware','vuln','phishing','malware','cert','cert_fr','typosquat','reputation','cti','presse','leaks','paste','presse_cyber','presse_locale')
    ) THEN
      RAISE NOTICE 'migrate-205 : famille hors contrat présente — CHECK % laissé en place', con.conname;
      CONTINUE;
    END IF;
    RAISE NOTICE 'migrate-205 : remplace % par la liste des 14 familles', con.conname;
    EXECUTE format('ALTER TABLE event DROP CONSTRAINT %I', con.conname);
    EXECUTE format('ALTER TABLE event ADD CONSTRAINT %I %s', con.conname, wanted);
    changed := true;
  END LOOP;
  IF NOT changed THEN
    RAISE NOTICE 'migrate-205 : aucun CHECK à élargir';
  END IF;
END $$;

