INSERT INTO event (
  dedup_key, family, assertion_type, title, summary, langue,
  observed_at, valid_at, at, collected_at, severity, confidence,
  source_id, source_url, evidence, geo_type, admission_rule,
  regional, regional_motif, dept, pertinence_score, pertinence_rule
)
SELECT x.d, 'presse_locale', 'ambient_signal', x.t, x.s, 'fr',
       x.o, x.o, now(), now(), 2, 'C3',
       x.id, x.u, x.ev, 'unknown', 'dept',
       true, 'departement', x.dept, 0, 'dept'
  FROM seed x
 WHERE NOT EXISTS (SELECT 1 FROM event e WHERE e.source_url = x.u)
ON CONFLICT (dedup_key) DO NOTHING;

COMMIT;
